import{_ as a,o as t,c as r,a2 as s}from"./chunks/framework.CWdVbaJB.js";const m=JSON.parse('{"title":"Workspace","description":"","frontmatter":{"title":"Workspace"},"headers":[],"relativePath":"platform/workspace.md","filePath":"platform/workspace.md"}'),o={name:"platform/workspace.md"};function n(i,e,l,c,d,p){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="workspace" tabindex="-1">Workspace <a class="header-anchor" href="#workspace" aria-label="Permalink to &quot;Workspace&quot;">​</a></h1><p>A workspace is the top-level isolation boundary in SHAVIRA. All users, projects, traces, findings, and API keys belong to exactly one workspace.</p><h2 id="workspace-isolation" tabindex="-1">Workspace Isolation <a class="header-anchor" href="#workspace-isolation" aria-label="Permalink to &quot;Workspace Isolation&quot;">​</a></h2><p>Workspaces provide hard data boundaries:</p><ul><li>Users in one workspace cannot see data from another</li><li>API keys are scoped to the workspace that created them</li><li>All database queries are filtered by <code>workspace_id</code></li></ul><h2 id="automatic-workspace-creation" tabindex="-1">Automatic Workspace Creation <a class="header-anchor" href="#automatic-workspace-creation" aria-label="Permalink to &quot;Automatic Workspace Creation&quot;">​</a></h2><p>When a new user signs up, a personal workspace is created automatically. The user becomes the workspace admin.</p><h2 id="members" tabindex="-1">Members <a class="header-anchor" href="#members" aria-label="Permalink to &quot;Members&quot;">​</a></h2><h3 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Roles&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Role</th><th>Permissions</th></tr></thead><tbody><tr><td><strong>Admin</strong></td><td>Full access — manage users, projects, settings, API keys</td></tr><tr><td><strong>Member</strong></td><td>View traces and findings in assigned projects</td></tr></tbody></table><h3 id="inviting-users" tabindex="-1">Inviting Users <a class="header-anchor" href="#inviting-users" aria-label="Permalink to &quot;Inviting Users&quot;">​</a></h3><p>Admins can invite users to the workspace:</p><ol><li>Go to <strong>Admin &gt; Users</strong></li><li>Choose <strong>Send invite</strong> or <strong>Create account</strong></li><li>Enter the user&#39;s name, email, and role</li></ol><p><strong>Send invite</strong> generates a temporary password and sends an email. The user must change their password on first login.</p><p><strong>Create account</strong> generates a temporary password shown to the admin. Share it securely with the user.</p><h3 id="removing-users" tabindex="-1">Removing Users <a class="header-anchor" href="#removing-users" aria-label="Permalink to &quot;Removing Users&quot;">​</a></h3><p>Admins can remove users from the workspace. This:</p><ul><li>Removes the user from all projects</li><li>Revokes all their API keys</li><li>Does not delete traces they created</li></ul><h2 id="workspace-deletion" tabindex="-1">Workspace Deletion <a class="header-anchor" href="#workspace-deletion" aria-label="Permalink to &quot;Workspace Deletion&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>Workspace deletion permanently removes all data — users, projects, traces, findings, API keys, and cost records. This cannot be undone.</p></div><p>Only workspace admins can delete a workspace. Go to <strong>Settings &gt; Danger Zone &gt; Delete Workspace</strong>.</p>',21)])])}const u=a(o,[["render",n]]);export{m as __pageData,u as default};
